1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.rest.function.owner.IdentityKey;
12	import org.springframework.samples.petclinic.util.CheckDigit;
13	import org.springframework.samples.petclinic.util.ContactPreference;
14	import org.springframework.samples.petclinic.util.CustomerCode;
15	import org.springframework.samples.petclinic.util.Locality;
16	import org.springframework.samples.petclinic.util.MembershipLevel;
17	
18	import java.util.Collection;
19	import java.util.List;
20	
21	/**
22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public interface OwnerMapper {
26	
27	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
28	    @Mapping(target = "initials", expression = "java(initials(owner))")
29	    @Mapping(target = "locality", expression = "java(locality(owner))")
30	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
31	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
32	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
33	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
34	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /** The owner's name formatted as 'LastName, FirstName'. */
38	    default String displayName(Owner owner) {
39	        return owner == null ? null : owner.getLastName() + ", " + owner.getFirstName();
40	    }
41	
42	    /**
43	     * The canonical region taken from the owner's region-and-hash identity: the REGION portion of the
44	     * customerCode (see {@link CustomerCode}). Falls back to deriving the region directly from the
45	     * city and postcode (see {@link Locality}) for an owner that has no customerCode yet.
46	     */
47	    default String locality(Owner owner) {
48	        if (owner == null) {
49	            return null;
50	        }
51	        String region = CustomerCode.regionOf(owner.getCustomerCode());
52	        return region != null ? region : Locality.of(owner.getCity(), owner.getPostcode());
53	    }
54	
55	    /** The upper-cased first letters of the first and last name, e.g. 'J.S.'. */
56	    default String initials(Owner owner) {
57	        return owner == null ? null
58	            : Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
59	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
60	    }
61	
62	    /**
63	     * The owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where YY is the
64	     * last two digits of the registration date's year, e.g. 'NSW-1A2B3C4D-M26'.
65	     */
66	    default String membershipNumber(Owner owner) {
67	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
68	            return null;
69	        }
70	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
71	    }
72	
73	    /**
74	     * The owner's check digit (see {@link CheckDigit}): the Luhn check digit over the digits of the
75	     * customer code.
76	     */
77	    default Integer checkDigit(Owner owner) {
78	        return owner == null ? null : CheckDigit.of(owner.getCustomerCode());
79	    }
80	
81	    /**
82	     * The owner's membership level (see {@link MembershipLevel}): a number from 1 to 3 that starts
83	     * at 1, gains 1 for a present email address and 1 for a unique name (namesakeCount is zero),
84	     * capped at 3.
85	     */
86	    default Integer membershipLevel(Owner owner) {
87	        return MembershipLevel.of(owner);
88	    }
89	
90	    /**
91	     * The owner's preferred contact channel (see {@link ContactPreference}): 'EMAIL' when an email
92	     * address is present, otherwise 'PHONE'.
93	     */
94	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
95	        ContactPreference preference = ContactPreference.of(owner);
96	        return preference == null ? null : OwnerDto.ContactPreferenceEnum.valueOf(preference.name());
97	    }
98	
99	    /**
100	     * The owner's derived identity key (see {@link IdentityKey}): the canonical telephone, email and
101	     * household id joined by '|'. The single value duplicate detection consolidates on.
102	     */
103	    default String identityKey(Owner owner) {
104	        return owner == null ? null : IdentityKey.forOwner(owner);
105	    }
106	
107	    Owner toOwner(OwnerDto ownerDto);
108	
109	    @Mapping(target = "id", ignore = true)
110	    @Mapping(target = "pets", ignore = true)
111	    Owner toOwner(OwnerFieldsDto ownerDto);
